SELECT 
FROM int_execution

    AND task_code = #{taskCode}
    AND master_id = #{masterId}
    AND business_key = #{businessKey}
    AND status = #{status}

        AND create_time >= #{params.beginTime}


        AND create_time <= #{params.endTime}


ORDER BY create_time DESC, execution_id DESC

mapper.update:
UPDATE int_execution
SET status = 'RUNNING', start_time = #{startTime}, update_time = #{startTime}
WHERE execution_id = #{executionId} AND status = 'PENDING'

UPDATE int_execution
SET stage = #{stage}, update_time = #{updateTime}
WHERE execution_id = #{executionId} AND status = 'RUNNING'
